#!/usr/bin/env bash
set -euo pipefail
database_discover() { local out="$1"; jq -n --arg mysql "$(command -v mysql >/dev/null 2>&1 && echo true || echo false)" --arg pg "$(command -v psql >/dev/null 2>&1 && echo true || echo false)" --arg redis "$(command -v redis-cli >/dev/null 2>&1 && echo true || echo false)" --arg mongo "$(command -v mongodump >/dev/null 2>&1 && echo true || echo false)" '{mysql:($mysql=="true"),postgresql:($pg=="true"),redis:($redis=="true"),mongodb:($mongo=="true")}' >"$out"; }
database_backup() { local dir="$1/databases"; mkdir -p "$dir"; if command -v mysqldump >/dev/null 2>&1; then mysqldump --all-databases --single-transaction --quick >"$dir/mysql.sql" 2>/dev/null || log_warn "MySQL dump skipped"; fi; if command -v pg_dumpall >/dev/null 2>&1; then sudo -u postgres pg_dumpall >"$dir/postgresql.sql" 2>/dev/null || pg_dumpall >"$dir/postgresql.sql" 2>/dev/null || log_warn "PostgreSQL dump skipped"; fi; if command -v redis-cli >/dev/null 2>&1; then redis-cli BGSAVE >/dev/null 2>&1 || redis-cli SAVE >/dev/null 2>&1 || log_warn "Redis save skipped"; fi; if command -v mongodump >/dev/null 2>&1; then mongodump --archive="$dir/mongodb.archive" >/dev/null 2>&1 || log_warn "MongoDB dump skipped"; fi; }
database_restore() { local dir="$1/databases"; [[ -d "$dir" ]] || return 0; [[ -f "$dir/mysql.sql" ]] && command -v mysql >/dev/null 2>&1 && mysql <"$dir/mysql.sql" || true; [[ -f "$dir/postgresql.sql" ]] && command -v psql >/dev/null 2>&1 && (sudo -u postgres psql -f "$dir/postgresql.sql" || psql -f "$dir/postgresql.sql") || true; }
